import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.security.SecureRandom

/**
 * Secure message framing protocol handler.
 * Handles variable-length binary messages with encryption.
 * 
 * Frame format:
 *   [4 bytes: total frame length (big-endian)]
 *   [4 bytes: payload offset within frame]
 *   [4 bytes: payload length]
 *   [12 bytes: GCM nonce]
 *   [variable: encrypted payload + GCM tag]
 */
class MessageFrameHandler(
    private val masterKey: ByteArray,
    private val maxMessageSize: Int = 65536
) {
    private val sessions = ConcurrentHashMap<String, SessionState>()
    private val secureRandom = SecureRandom()

    data class SessionState(
        val sessionId: String,
        val sequenceNumber: Long,
        val keyMaterial: ByteArray
    )

    data class ParsedFrame(
        val payload: ByteArray,
        val frameLength: Int,
        val payloadOffset: Int,
        val payloadLength: Int
    )

    /**
     * Validates frame boundaries to prevent out-of-bounds access.
     * Ensures payload region falls within the frame buffer.
     */
    private fun validateFrameBounds(
        buffer: ByteArray,
        payloadOffset: Int,
        payloadLength: Int
    ): Boolean {
        // Ensure offset is non-negative
        if (payloadOffset < 0) return false
        // Ensure length is non-negative  
        if (payloadLength < 0) return false
        // Ensure offset is within buffer first
        if (payloadOffset > buffer.size) return false
        // Ensure payload region doesn't exceed buffer
        // Safe from overflow: since payloadOffset <= buffer.size,
        // buffer.size - payloadOffset cannot underflow
        if (payloadLength > buffer.size - payloadOffset) return false
        // Ensure minimum viable payload (at least GCM tag)
        if (payloadLength < 16) return false
        return true
    }

    /**
     * Extracts raw payload bytes from a validated frame buffer.
     */
    private fun extractPayload(
        buffer: ByteArray,
        payloadOffset: Int,
        payloadLength: Int
    ): ByteArray {
        val payload = ByteArray(payloadLength)
        System.arraycopy(buffer, payloadOffset, payload, 0, payloadLength)
        return payload
    }

    /**
     * Decrypts an AES-GCM encrypted payload.
     */
    private fun decryptPayload(
        encryptedPayload: ByteArray,
        nonce: ByteArray,
        associatedData: ByteArray
    ): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
        cipher.updateAAD(associatedData)
        return cipher.doFinal(encryptedPayload)
    }

    /**
     * Parses and validates an incoming binary frame.
     * 
     * Security: validates all length fields before any buffer access.
     * Uses bounds checking to prevent buffer over-read attacks.
     */
    fun parseFrame(rawData: ByteArray): ParsedFrame? {
        // Minimum frame size: 4 (frame len) + 4 (offset) + 4 (payload len) + 12 (nonce) = 24
        if (rawData.size < 24) return null

        val headerBuffer = ByteBuffer.wrap(rawData, 0, 12)
            .order(ByteOrder.BIG_ENDIAN)

        val frameLength = headerBuffer.getInt()
        val payloadOffset = headerBuffer.getInt() 
        val payloadLength = headerBuffer.getInt()

        // Validate frame length matches actual data
        if (frameLength != rawData.size) return null

        // Enforce maximum message size policy
        if (payloadLength > maxMessageSize) return null

        // Validate payload bounds within frame
        if (!validateFrameBounds(rawData, payloadOffset, payloadLength)) {
            return null
        }

        // Extract nonce (bytes 12-23)
        val nonce = ByteArray(12)
        System.arraycopy(rawData, 12, nonce, 0, 12)

        // Extract encrypted payload
        val encryptedPayload = extractPayload(rawData, payloadOffset, payloadLength)

        // Build associated data for authentication (frame header)
        val aad = ByteArray(12)
        System.arraycopy(rawData, 0, aad, 0, 12)

        // Decrypt and authenticate
        val decryptedPayload = try {
            decryptPayload(encryptedPayload, nonce, aad)
        } catch (e: Exception) {
            return null // Authentication failed
        }

        return ParsedFrame(
            payload = decryptedPayload,
            frameLength = frameLength,
            payloadOffset = payloadOffset,
            payloadLength = payloadLength
        )
    }

    /**
     * Processes a multi-frame message stream.
     * Handles frame reassembly with sequence validation.
     */
    fun processStream(
        sessionId: String,
        streamData: ByteArray
    ): List<ByteArray> {
        val results = mutableListOf<ByteArray>()
        var position = 0

        while (position < streamData.size) {
            // Need at least 4 bytes for frame length
            if (streamData.size - position < 4) break

            val frameLenBuf = ByteBuffer.wrap(streamData, position, 4)
                .order(ByteOrder.BIG_ENDIAN)
            val frameLen = frameLenBuf.getInt()

            // Validate frame length
            if (frameLen < 24 || frameLen > maxMessageSize) break
            if (position + frameLen > streamData.size) break

            // Extract single frame
            val frameData = ByteArray(frameLen)
            System.arraycopy(streamData, position, frameData, 0, frameLen)

            val parsed = parseFrame(frameData)
            if (parsed != null) {
                results.add(parsed.payload)
            }

            position += frameLen
        }

        return results
    }

    /**
     * Creates an encrypted frame for outbound messages.
     */
    fun createFrame(payload: ByteArray): ByteArray {
        if (payload.size > maxMessageSize) {
            throw IllegalArgumentException("Payload exceeds maximum size")
        }

        // Generate a fresh, unique nonce for this single encryption operation.
        val nonce = ByteArray(12)
        secureRandom.nextBytes(nonce)

        val payloadOffset = 24 // Header (12) + nonce (12)

        // Compute encrypted size deterministically: plaintext + 16-byte GCM tag.
        val gcmTagBytes = 16
        val encryptedSize = payload.size + gcmTagBytes
        val frameLength = 24 + encryptedSize

        // Build the frame and header first so the AAD (header bytes) is finalized
        // BEFORE encryption. This lets us encrypt exactly once with the nonce.
        val frame = ByteArray(frameLength)
        val header = ByteBuffer.wrap(frame, 0, 12)
            .order(ByteOrder.BIG_ENDIAN)
        header.putInt(frameLength)
        header.putInt(payloadOffset)
        header.putInt(encryptedSize)

        System.arraycopy(nonce, 0, frame, 12, 12)

        // AAD is the frame header (12 bytes)
        val aad = ByteArray(12)
        System.arraycopy(frame, 0, aad, 0, 12)

        // Encrypt exactly once with the fresh nonce and the finalized AAD.
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        cipher.updateAAD(aad)
        val encrypted = cipher.doFinal(payload)

        System.arraycopy(encrypted, 0, frame, 24, encrypted.size)

        return frame
    }
}
